// =============================================================
//  data_bond_events.js … 「特別な関係」ごとのイベント（各関係3種・計12種）
//
//  ・恋人 / 無二の相棒 / 永遠の主従 / 家族 のそれぞれに3つずつ
//  ・場面の描写は英霊の「性格」（PERSONAS：高潔・王者・豪快・クール・温和・自由・影・学究・狂戦士）ごと、
//    台詞は「話し方」（polite / regal / rough / old / cool / bright / mute）ごとに書き分けている
//  ・さらに英霊ごとの名前・宝具・願い・固有の台詞（SIG）を織り込む
//  ・結果はどれも能力値が大きく上がる（関係が深まった証）
//  ・発生：夜の「〇〇と語らう」で高確率、または通常のランダムイベントとして
//  ・この版（性的描写無し版）では、恋人のイベントも性的な描写を含まない
// =============================================================

// 性格ごとの文章（無ければ knight の文章を使う）
// ob＝オベロン専用の文章（言葉が捻じ曲がる、特別な話し方のため。data_oberon.js 参照）
// 英霊ID（mash / meltryllis / artoria_caster など）をキーにした、その英霊専用の文章があればそれを使う
// 藤丸シナリオでは「<id>_c」（カルデアで絆を結んだ、その英霊）を優先する
function svOwn(map) { const sv = servantOf(G); return (typeof isFuji === 'function' && isFuji() && map[sv.id + '_c']) || map[sv.id] || (sv.id === 'oberon' && map.ob) || null; }
// 「生前」にあたる言葉（生前を持たない英霊のために）
const SV_PAST = { mash: 'デミ・サーヴァントになる前', artoria_caster: '妖精國を旅していた頃', meltryllis: () => (isFuji() ? 'カルデアに来る前' : 'この時代に喚ばれる前'), oberon: '妖精國にいた頃' };
function svPast() { const v = SV_PAST[sid3()]; return (typeof v === 'function' ? v() : v) || '生前'; }
function sid3() { return G && G.servant ? G.servant.id : ''; }
function PV(map) { const sv = servantOf(G); return fmt(svOwn(map) || map[sv.persona] || map.knight); }
// 話し方ごとの台詞（言葉を話さない英霊は地の文）
function RV(map) {
  const reg = voiceOf(servantOf(G)).reg;
  if (reg === 'mute') return fmt(map.mute);
  const ob = svOwn(map);
  return `<p class="quote">${applyTic(fmt(ob || map[reg] || map.polite))}</p>`;
}
// 能力値などをまとめて上げ、注記を返す
function rboost(o) {
  const parts = [];
  for (const [k, n] of Object.entries(o)) {
    if (k === 'bond') { bond(n); parts.push(`絆+${n}`); }
    else if (k === 'hp') { hp(n); parts.push(`HP+${n}`); }
    else if (k === 'shp') { shp(n); parts.push(`${SV()}のHP+${n}`); }
    else if (k === 'mp') { mp(n); parts.push(`${SV()}の魔力+${n}`); }
    else if (k === 'od') { od(n); parts.push(`オド+${n}`); }
    else { gain(k, n); parts.push(`${STAT_LABEL[k]}+${n}`); }
  }
  return `<span class="note">（${parts.join(' ')}）</span>`;
}
const relIs = k => () => G.phase === 'war' && !!G.servant && G.servant.special === k;
const svNP = () => { const s = servantOf(G); return s.np ? `「${s.np}」` : '宝具'; };

